import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Environmental Variables","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/mac-os-installation/environmental-variables.md","filePath":"getting-started/mac-os-installation/environmental-variables.md"}'),n={name:"getting-started/mac-os-installation/environmental-variables.md"};function l(h,s,p,o,d,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="environmental-variables" tabindex="-1">Environmental Variables <a class="header-anchor" href="#environmental-variables" aria-label="Permalink to &quot;Environmental Variables&quot;">​</a></h1><p>Tradeboard reads its configuration from a <code>.env</code> file in the application directory. Create it from the <code>.sample.env</code> that shipped with the Tradeboard release you checked out:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tradeboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .sample.env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>The checked-out <code>.sample.env</code> is the authoritative list of variables. Do not paste an environment block from a blog post, an older guide, or another machine. The current template declares <code>ENV_CONFIG_VERSION = &#39;1.0.7&#39;</code> and contains 97 active keys.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Never copy an <code>APP_KEY</code>, <code>API_KEY_PEPPER</code> or <code>FERNET_SALT</code> value out of documentation, out of <code>.sample.env</code>, or out of another installation. <code>.sample.env</code> ships deliberate placeholders:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">APP_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRADEBOARD_PLACEHOLDER_APP_KEY_REGENERATE_BEFORE_USE&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">API_KEY_PEPPER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRADEBOARD_PLACEHOLDER_API_KEY_PEPPER_REGENERATE_BEFORE_USE&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FERNET_SALT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;TRADEBOARD_PLACEHOLDER_FERNET_SALT_REGENERATE_BEFORE_USE&#39;</span></span></code></pre></div><p>On first run Tradeboard detects these placeholders, generates fresh values with <code>secrets.token_hex(32)</code>, writes them back to your <code>.env</code>, and prints a one-time <code>[Tradeboard first-run setup]</code> message. The install scripts do the same thing. In normal use you never edit these three lines by hand.</p></div><h3 id="what-you-must-edit" tabindex="-1">What you must edit <a class="header-anchor" href="#what-you-must-edit" aria-label="Permalink to &quot;What you must edit&quot;">​</a></h3><h4 id="broker-credentials" tabindex="-1">Broker credentials <a class="header-anchor" href="#broker-credentials" aria-label="Permalink to &quot;Broker credentials&quot;">​</a></h4><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_API_KEY&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_API_SECRET&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">REDIRECT_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/&lt;broker&gt;/callback&#39;</span></span></code></pre></div><p>Replace <code>&lt;broker&gt;</code> in <code>REDIRECT_URL</code> with your broker&#39;s key, for example <code>http://127.0.0.1:5000/zerodha/callback</code>, and register the same URL in your broker&#39;s developer console.</p><p>XTS-based brokers (<code>fivepaisaxts</code>, <code>compositedge</code>, <code>ibulls</code>, <code>iifl</code>, <code>jainamxts</code>, <code>rmoney</code>, <code>wisdom</code>) also need a separate market-data login:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_KEY_MARKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_MARKET_API_KEY&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">BROKER_API_SECRET_MARKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;YOUR_BROKER_MARKET_API_SECRET&#39;</span></span></code></pre></div><p>Leave these at their placeholder values for every other broker.</p><h3 id="defaults-you-normally-leave-alone" tabindex="-1">Defaults you normally leave alone <a class="header-anchor" href="#defaults-you-normally-leave-alone" aria-label="Permalink to &quot;Defaults you normally leave alone&quot;">​</a></h3><h4 id="application-and-realtime-endpoints" tabindex="-1">Application and realtime endpoints <a class="header-anchor" href="#application-and-realtime-endpoints" aria-label="Permalink to &quot;Application and realtime endpoints&quot;">​</a></h4><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLASK_HOST_IP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLASK_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;5000&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLASK_DEBUG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;False&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FLASK_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;development&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;8765&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBSOCKET_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ws://127.0.0.1:8765&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ZMQ_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ZMQ_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;5555&#39;</span></span></code></pre></div><p>The Flask app listens on port 5000 and the WebSocket proxy on port 8765. <code>WEBSOCKET_HOST</code> is pinned to <code>127.0.0.1</code> for macOS compatibility, and <code>ZMQ_HOST</code> must stay on loopback: ZeroMQ is the unauthenticated internal bus between the broker adapters and the WebSocket proxy, so binding it to <code>0.0.0.0</code> would publish the raw tick feed to anything that can reach the port.</p><p><code>FLASK_DEBUG=&#39;True&#39;</code> enables the Werkzeug interactive debugger, which executes arbitrary Python for anyone who can reach it. Tradeboard refuses to start if <code>FLASK_DEBUG=&#39;True&#39;</code> is combined with a non-loopback <code>FLASK_HOST_IP</code>.</p><h4 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h4><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/tradeboard.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LATENCY_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/latency.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LOGS_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/logs.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HEALTH_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/health.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SANDBOX_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sqlite:///db/sandbox.db&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HISTORIFY_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;db/historify.duckdb&#39;</span></span></code></pre></div><p>Historical data lives in DuckDB, everything else in SQLite. The <code>db/</code> directory is created for you on first start.</p><h4 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h4><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LOGIN_RATE_LIMIT_MIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;5 per minute&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">LOGIN_RATE_LIMIT_HOUR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;25 per hour&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RESET_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;15 per hour&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">API_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;50 per second&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ORDER_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10 per second&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SMART_ORDER_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10 per second&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">WEBHOOK_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;100 per minute&quot;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">STRATEGY_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;200 per minute&quot;</span></span></code></pre></div><h4 id="session-behaviour" tabindex="-1">Session behaviour <a class="header-anchor" href="#session-behaviour" aria-label="Permalink to &quot;Session behaviour&quot;">​</a></h4><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_EXPIRY_TIME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;03:00&#39;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DISABLE_SESSION_EXPIRY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;false&#39;</span></span></code></pre></div><p>Sessions expire daily at 03:00 IST because Indian broker tokens do. Set <code>DISABLE_SESSION_EXPIRY = &#39;true&#39;</code> only for a 24/7 crypto broker such as Delta Exchange.</p><h4 id="ngrok" tabindex="-1">Ngrok <a class="header-anchor" href="#ngrok" aria-label="Permalink to &quot;Ngrok&quot;">​</a></h4><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">NGROK_ALLOW</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;FALSE&#39;</span></span></code></pre></div><p>Set to <code>&#39;TRUE&#39;</code> and point <code>HOST_SERVER</code> at your Ngrok domain if you tunnel the instance. See <a href="./ngrok-config.html">Ngrok Config</a>.</p><h3 id="broker-allowlist" tabindex="-1">Broker allowlist <a class="header-anchor" href="#broker-allowlist" aria-label="Permalink to &quot;Broker allowlist&quot;">​</a></h3><p><code>VALID_BROKERS</code> is a comma-separated list of enabled broker plugin keys. The release template enables all 36:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">VALID_BROKERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fivepaisa,fivepaisaxts,aliceblue,angel,arrow,compositedge,dhan,dhan_sandbox,definedge,deltaexchange,firstock,flattrade,fyers,groww,hdfcsecurities,hdfcsky,ibulls,iifl,iiflcapital,indmoney,jainamxts,kotak,motilal,mstock,nubra,paytm,pocketful,rmoney,samco,shoonya,tradejini,tradesmart,upstox,wisdom,zebu,zerodha&#39;</span></span></code></pre></div><p>A broker being listed does not guarantee every optional exchange, GTT, historical-data or streaming capability. See <a href="./../../connect-brokers/brokers/README.html">Brokers</a>.</p><h3 id="updating-an-existing-installation" tabindex="-1">Updating an existing installation <a class="header-anchor" href="#updating-an-existing-installation" aria-label="Permalink to &quot;Updating an existing installation&quot;">​</a></h3><ol><li>Back up <code>.env</code> before every upgrade: <code>cp .env .env.backup</code>.</li><li>Compare <code>ENV_CONFIG_VERSION</code> in your <code>.env</code> against the new <code>.sample.env</code>.</li><li>Copy across only the new lines. Never run <code>cp .sample.env .env</code> over a working installation: it discards your broker credentials and replaces <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code>, which permanently invalidates every stored password hash and every encrypted broker token.</li><li>Restart Tradeboard and read the startup configuration check before enabling automation.</li></ol><p>Never commit <code>.env</code>, paste it into an issue, or include it in a screenshot. It holds broker credentials, application secrets and deployment policy.</p>`,35)])])}const F=a(n,[["render",l]]);export{c as __pageData,F as default};
